mapper.select:
SELECT MAX(t.id) AS id, SUM(activate_status) activate_count, COUNT(1) AS proc_count FROM (
    SELECT id,(proc_type = 5) activate_status FROM p_user_proc WHERE id > #{settledProcId} ORDER BY id LIMIT #{limitSize}
) t

SELECT MAX(t.id) AS id, SUM(vip_upgrade_status) vip_upgrade_count, COUNT(1) AS proc_count FROM (
    SELECT id,(proc_type = 10) vip_upgrade_status FROM p_user_proc WHERE id > #{settledProcId} ORDER BY id LIMIT #{limitSize}
) t
